def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    def rkey(maxlen, alpha='0123456789'):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(1, maxlen)))

    def session(q, maxlen, pool_size, alpha='0123456789', probs=(0.4, 0.4, 0.2), vmax=10**9):
        pool = []
        base = rkey(maxlen, alpha)
        for _ in range(pool_size):
            r = rng.random()
            if r < 0.35 and pool:
                # prefix or extension of an existing key
                b = rng.choice(pool)
                if rng.random() < 0.5:
                    k = b[:rng.randint(1, len(b))]
                else:
                    k = (b + rkey(max(1, maxlen - len(b)), alpha))[:maxlen]
            else:
                k = rkey(maxlen, alpha)
            pool.append(k)
        ops = []
        for _ in range(q):
            k = rng.choice(pool)
            x = rng.random()
            if x < probs[0]:
                ops.append(f'insert {k} {rng.randint(0, vmax)}')
            elif x < probs[0] + probs[1]:
                ops.append(f'get {k}')
            else:
                ops.append(f'delete {k}')
        return fmt(ops)

    tests = [
        fmt(['get 5']),
        fmt(['delete 0']),
        fmt(['insert 0 0', 'get 0', 'insert 0 5', 'get 0', 'delete 0', 'get 0', 'delete 0']),
        fmt(['insert 12 1', 'insert 123 2', 'insert 1 3', 'delete 12', 'get 123', 'get 12', 'get 1', 'delete 123', 'get 1', 'get 123']),
        fmt(['insert 007 1', 'insert 7 2', 'get 007', 'delete 07', 'get 7']),
    ]
    for _ in range(25):
        tests.append(session(rng.randint(5, 25), rng.randint(1, 6), rng.randint(2, 8), alpha=rng.choice(['01', '0123456789', '12'])))
    # medium
    tests.append(session(3000, 30, 800))
    # max size: 30000 ops, keys up to 50 digits, many distinct keys, mostly inserts then gets/deletes
    for _ in range(2):
        pool = [rkey(50) for _ in range(12000)]
        ops = []
        for k in pool:
            ops.append(f'insert {k} {rng.randint(0, 10**9)}')
        for _ in range(30000 - len(ops)):
            k = rng.choice(pool)
            x = rng.random()
            if x < 0.6:
                ops.append(f'get {k}')
            elif x < 0.8:
                ops.append(f'delete {k}')
            else:
                ops.append(f'insert {k} {rng.randint(0, 10**9)}')
        tests.append(fmt(ops[:30000]))
    # shared long prefixes (trie-heavy)
    pre = ''.join(rng.choice('0123456789') for _ in range(45))
    pool = [pre[:rng.randint(1, 45)] + ''.join(rng.choice('0123456789') for _ in range(rng.randint(0, 5))) for _ in range(15000)]
    pool = [k[:50] for k in pool]
    ops = [f'insert {k} {rng.randint(0, 10**9)}' for k in pool]
    for _ in range(30000 - len(ops)):
        k = rng.choice(pool)
        ops.append(rng.choice([f'get {k}', f'delete {k}', f'get {k}']))
    tests.append(fmt(ops))
    # all inserts of distinct 50-digit keys
    ops = [f'insert {rkey(50)} {rng.randint(0, 10**9)}' for _ in range(30000)]
    tests.append(fmt(ops))
    return tests

